   104→void AWjWorldGameStatePlay::OnRep_GamePhase()
   105→{
   106→	switch (CurrentPhase)
   107→	{
   108→	case EGamePhase::Ready:
   109→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Ready"));
   110→		break;
   111→	case EGamePhase::Playing:
   112→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Started"));
   113→		break;
   114→	case EGamePhase::Finished:
   115→		// 결과 표시는 OnRep_GameResult에서 처리
   116→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Finished"));
   117→		break;
   118→	}
   119→
   120→	UE_LOG(LogWjWorld, Log, TEXT("GameState: Phase changed to %d"), static_cast<int32>(CurrentPhase));
   121→}
