   123→void AWjWorldGameStatePlay::OnRep_IsGameStartCountDownReady()
   124→{
   125→	if (bIsGameStartCountDownReady)
   126→	{
   127→		UWorld* World = GetWorld();
   128→		if (!World) return;
   129→
   130→		APlayerController* PC = World->GetFirstPlayerController();
   131→		if (!PC) return;
   132→
   133→		AWjWorldHUDPlay* HUD = PC->GetHUD<AWjWorldHUDPlay>();
   134→		if (!HUD) return;
   135→
   136→		// 늦게 참여한 클라이언트를 위해 남은 시간 계산
   137→		float RemainingTime = StartCountDownTime;
   138→		if (CountdownStartServerTime > 0.0)
   139→		{
   140→			double CurrentServerTime = GetServerWorldTimeSeconds();
   141→			double Elapsed = CurrentServerTime - CountdownStartServerTime;
   142→			RemainingTime = FMath::Max(0.0f, StartCountDownTime - static_cast<float>(Elapsed));
   143→		}
   144→
   145→		HUD->StartGameStartCountDown(RemainingTime);
   146→
   147→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Game Start Countdown Ready - %f seconds (original: %f)"), RemainingTime, StartCountDownTime);
   148→	}
   149→}
