   192→void AWjWorldGameStatePlay::OnRep_GameResult()
   193→{
   194→	if (!bGameResultReady) return;
   195→
   196→	UWorld* World = GetWorld();
   197→	if (!World) return;
   198→
   199→	APlayerController* PC = World->GetFirstPlayerController();
   200→	if (!PC) return;
   201→
   202→	AWjWorldHUDPlay* HUD = PC->GetHUD<AWjWorldHUDPlay>();
   203→	if (!HUD) return;
   204→
   205→	FString LocalPlayerName;
   206→	if (PC->PlayerState)
   207→	{
   208→		LocalPlayerName = PC->PlayerState->GetPlayerName();
   209→	}
   210→
   211→	FString ResultText;
   212→	if (bGameHasWinner)
   213→	{
   214→		if (LocalPlayerName == WinnerPlayerName)
   215→		{
   216→			ResultText = TEXT("Victory!");
   217→		}
   218→		else
   219→		{
   220→			ResultText = FString::Printf(TEXT("%s Wins!"), *WinnerPlayerName);
   221→		}
   222→	}
   223→	else
   224→	{
   225→		ResultText = TEXT("Draw!");
   226→	}
   227→
   228→	HUD->ShowGameResultText(ResultText, 5.0f);
   229→
   230→	// 1인 플레이 시 스탯/보상 제외
   231→	const bool bShouldRecordStats = (InitialPlayerCount > 1);
   232→
   233→	// 스탯 기록 (각 클라이언트가 자신의 스탯만 기록)
   234→	// StatNamespace 기반 동적 스탯 키 생성
   235→	UWjWorldStatsSubsystem* Stats = GetGameInstance()->GetSubsystem<UWjWorldStatsSubsystem>();
   236→	if (bShouldRecordStats && Stats && PC->PlayerState && !StatNamespace.IsNone())
   237→	{
   238→		FString NS = StatNamespace.ToString();
   239→		Stats->IncrementLocalStat(FName(*FString::Printf(TEXT("%s_GamesPlayed"), *NS)));
   240→
   241→		if (bGameHasWinner && WinnerPlayerName == LocalPlayerName)
   242→		{
   243→			Stats->IncrementLocalStat(FName(*FString::Printf(TEXT("%s_Wins"), *NS)));
   244→		}
   245→		else
   246→		{
   247→			Stats->IncrementLocalStat(FName(*FString::Printf(TEXT("%s_Losses"), *NS)));
   248→		}
   249→
   250→		Stats->StoreStats();
   251→	}
   252→	else if (!bShouldRecordStats)
   253→	{
   254→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Skipping stats/rewards for solo play (InitialPlayerCount=%d)"), InitialPlayerCount);
   255→	}
   256→
   257→	// 재화 보상 지급 (각 클라이언트가 자신의 보상 요청)
   258→	UWjWorldCurrencySubsystem* CurrencySub = GetGameInstance()->GetSubsystem<UWjWorldCurrencySubsystem>();
   259→	if (bShouldRecordStats && CurrencySub && PC->PlayerState)
   260→	{
   261→		bool bIsLocalPlayerWinner = bGameHasWinner && (WinnerPlayerName == LocalPlayerName);
   262→		CurrencySub->TriggerMatchReward(bIsLocalPlayerWinner);
   263→	}
   264→
   265→	UE_LOG(LogWjWorld, Log, TEXT("GameState: Game Result - %s"), *ResultText);
   266→}
