    48→void UWjWorldGameRuleApproachingWall::OnGameReady()
    49→{
    50→	if (!HasAuthority()) return;
    51→
    52→	Super::OnGameReady();
    53→
    54→	bIsGameReady = true;
    55→
    56→	if(BrickSpawner)
    57→	{
    58→		BrickSpawner->OnWallSpawnFinished.AddUObject(this, &UWjWorldGameRuleApproachingWall::OnWallSpawnFinished);
    59→
    60→		// MapOption에 따라 Random 또는 특정 WallName 스폰
    61→		AWjWorldGameModePlay* GameModePlay = GetGameModePlay();
    62→		FString CurrentMapOption = GameModePlay ? GameModePlay->GetMapOption() : FString();
    63→
    64→		if (CurrentMapOption.IsEmpty() || CurrentMapOption.Equals(TEXT("Random"), ESearchCase::IgnoreCase))
    65→		{
    66→			BrickSpawner->SpawnBricksRandomMapAsync();
    67→			UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnGameReady >>> SpawnBricksRandomMapAsync"));
    68→		}
    69→		else
    70→		{
    71→			BrickSpawner->SpawnBricksFromWallNameAsync(CurrentMapOption);
    72→			UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnGameReady >>> SpawnBricksFromWallNameAsync('%s')"), *CurrentMapOption);
    73→		}
    74→	}
    75→
    76→	InternalGameReadyProcess();
    77→
    78→	UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnGameReady()"));
    79→}
