    81→void UWjWorldGameRuleApproachingWall::OnGameStart()
    82→{
    83→	if (!HasAuthority()) return;
    84→
    85→	Super::OnGameStart();
    86→
    87→	UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnGameStart() - Players: %d (Min: %d)"),
    88→		TotalPlayerCount, MinimumPlayerCount);
    89→
    90→	bIsGameStarted = true;
    91→
    92→	// 엣지 케이스: 플레이어가 없거나 부족한 경우
    93→	if (TotalPlayerCount <= 0)
    94→	{
    95→		UE_LOG(LogWjWorld, Warning, TEXT("UWjWorldGameRuleApproachingWall::OnGameStart - No players, ending game"));
    96→		bGameOverConditionMet = true;
    97→		WinnerPlayer = nullptr;
    98→		OnGameEnd();
    99→		return;
   100→	}
   101→
   102→	// 엣지 케이스: 플레이어가 1명뿐인 경우 즉시 승리
   103→	if (TotalPlayerCount == 1 && AlivePlayerCount == 1)
   104→	{
   105→		UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnGameStart - Solo player wins by default"));
   106→		if (AlivePlayers.Num() > 0 && AlivePlayers[0].IsValid())
   107→		{
   108→			WinnerPlayer = AlivePlayers[0];
   109→		}
   110→		bGameOverConditionMet = true;
   111→		OnGameEnd();
   112→		return;
   113→	}
   114→
   115→	InternalGameStartProcess();
   116→}
