   118→void UWjWorldGameRuleApproachingWall::OnGameEnd()
   119→{
   120→	if (!HasAuthority()) return;
   121→
   122→	// 게임 결과 설정
   123→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   124→	if (GameState)
   125→	{
   126→		if (WinnerPlayer.IsValid())
   127→		{
   128→			GameState->SetGameResult(WinnerPlayer->GetPlayerName(), true);
   129→			UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnGameEnd - Winner: %s"), *WinnerPlayer->GetPlayerName());
   130→		}
   131→		else
   132→		{
   133→			// 승자 없음 (무승부 또는 모두 탈락)
   134→			GameState->SetGameResult(TEXT(""), false);
   135→			UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnGameEnd - No winner (Draw)"));
   136→		}
   137→	}
   138→
   139→	// 부모 클래스의 OnGameEnd 호출 (대기실 복귀 타이머 등)
   140→	Super::OnGameEnd();
