   160→void UWjWorldGameRuleApproachingWall::OnPlayerLeft(AWjWorldPlayerStatePlay* Player)
   161→{
   162→	Super::OnPlayerLeft(Player);
   163→
   164→	if (!HasAuthority() || !Player) return;
   165→
   166→	// 플레이어의 캐릭터 처리 (좀비 상태 방지)
   167→	APawn* PlayerPawn = Player->GetPawn();
   168→	AWjWorldCharacterPlay* PlayerCharacter = Cast<AWjWorldCharacterPlay>(PlayerPawn);
   169→	if (PlayerCharacter && !PlayerCharacter->IsEliminated())
   170→	{
   171→		// 캐릭터를 제거 상태로 만들고 파괴
   172→		PlayerCharacter->OnEliminated();
   173→		UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerLeft - Character eliminated for leaving player"));
   174→	}
   175→
   176→	// 플레이어가 나가면 생존자 목록에서 제거
   177→	if (AlivePlayers.Remove(Player) > 0)
   178→	{
   179→		AlivePlayerCount--;
   180→	}
   181→	TotalPlayerCount--;
   182→
   183→	UpdateGameData();
   184→
   185→	UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerLeft - Player: %s, Alive: %d, Total: %d"),
   186→		*Player->GetPlayerName(), AlivePlayerCount, TotalPlayerCount);
   187→
   188→	// 엣지 케이스: 모든 플레이어가 나간 경우
   189→	if (TotalPlayerCount <= 0)
   190→	{
   191→		UE_LOG(LogWjWorld, Warning, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerLeft - All players left, ending game"));
   192→		bGameOverConditionMet = true;
   193→		WinnerPlayer = nullptr; // 승자 없음
   194→		OnGameEnd();
   195→		return;
   196→	}
   197→
   198→	// 남은 플레이어 수 확인하여 승리 조건 체크
   199→	if (bIsGameStarted && CheckWinCondition())
   200→	{
   201→		// 마지막 생존자를 승자로 설정
   202→		if (AlivePlayerCount == 1 && AlivePlayers.Num() > 0)
   203→		{
   204→			for (const auto& AlivePlayer : AlivePlayers)
   205→			{
   206→				if (AlivePlayer.IsValid())
   207→				{
   208→					WinnerPlayer = AlivePlayer;
   209→					break;
   210→				}
   211→			}
   212→		}
   213→		bGameOverConditionMet = true;
   214→		OnGameEnd();
   215→	}
   216→}
