   218→void UWjWorldGameRuleApproachingWall::OnPlayerEliminated(AWjWorldCharacterPlay* EliminatedCharacter)
   219→{
   220→	if (!HasAuthority() || !EliminatedCharacter) return;
   221→
   222→	// 이미 제거된 캐릭터면 무시
   223→	if (EliminatedCharacter->IsEliminated()) return;
   224→
   225→	// 공격자가 있으면 킬 스탯 기록
   226→	AWjWorldCharacterPlay* Attacker = EliminatedCharacter->GetLastAttacker();
   227→	if (Attacker && !Attacker->IsEliminated())
   228→	{
   229→		AWjWorldPlayerStatePlay* AttackerPS = Attacker->GetPlayerState<AWjWorldPlayerStatePlay>();
   230→		if (AttackerPS)
   231→		{
   232→			RecordKillStat(AttackerPS);
   233→			UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerEliminated - Kill recorded for %s"),
   234→				*AttackerPS->GetPlayerName());
   235→		}
   236→	}
   237→
   238→	// 캐릭터 사망 처리
   239→	EliminatedCharacter->OnEliminated();
   240→
   241→	// PlayerState 가져오기 + AW PlayerData 업데이트
   242→	AWjWorldPlayerStatePlay* PlayerState = EliminatedCharacter->GetPlayerState<AWjWorldPlayerStatePlay>();
   243→	if (PlayerState)
   244→	{
   245→		if (UApproachingWallPlayerDataComponent* PlayerData = PlayerState->GetGameData<UApproachingWallPlayerDataComponent>())
   246→		{
   247→			PlayerData->OnEliminated();
   248→		}
   249→
   250→		// 생존자 목록에서 제거
   251→		if (AlivePlayers.Remove(PlayerState) > 0)
   252→		{
   253→			AlivePlayerCount--;
   254→		}
   255→
   256→		UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerEliminated - Player: %s eliminated. Alive: %d"),
   257→			*PlayerState->GetPlayerName(), AlivePlayerCount);
   258→	}
   259→
   260→	UpdateGameData();
   261→
   262→	// 엣지 케이스: 동시에 모두 제거된 경우 (AlivePlayerCount == 0)
   263→	if (AlivePlayerCount == 0)
   264→	{
   265→		UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerEliminated - All players eliminated simultaneously (Draw)"));
   266→		bGameOverConditionMet = true;
   267→		WinnerPlayer = nullptr; // 무승부
   268→		OnGameEnd();
   269→		return;
   270→	}
   271→
   272→	// 승리 조건 체크
   273→	if (bIsGameStarted && CheckWinCondition())
   274→	{
   275→		bGameOverConditionMet = true;
   276→
   277→		// 마지막 생존자를 승자로 설정
   278→		if (AlivePlayerCount == 1 && AlivePlayers.Num() > 0)
   279→		{
   280→			for (const auto& AlivePlayer : AlivePlayers)
   281→			{
   282→				if (AlivePlayer.IsValid())
   283→				{
   284→					WinnerPlayer = AlivePlayer;
   285→					break;
   286→				}
   287→			}
   288→		}
   289→
   290→		UE_LOG(LogWjWorld, Log, TEXT("Win condition met! Winner: %s"),
   291→			WinnerPlayer.IsValid() ? *WinnerPlayer->GetPlayerName() : TEXT("None"));
   292→
   293→		OnGameEnd();
   294→	}
   295→}
