   297→bool UWjWorldGameRuleApproachingWall::CheckWinCondition() const
   298→{
   299→	// 게임이 시작되지 않았으면 승리 조건 미충족
   300→	if (!bIsGameStarted) return false;
   301→
   302→	// 생존자가 1명 이하면 게임 종료
   303→	return AlivePlayerCount <= 1;
   304→}
