   311→void UWjWorldGameRuleApproachingWall::TickGameRule(float DeltaTime)
   312→{
   313→	if (!HasAuthority()) return;
   314→	if (!bGameStartInternalProcessDone) return;
   315→
   316→	TimeSinceLastBrickMoveSignal += DeltaTime;
   317→
   318→	if (TimeSinceLastBrickMoveSignal >= BrickMoveSignalInterval
   319→		&& bGameOverConditionMet == false)
   320→	{
   321→		// 오차 누적 방지
   322→		TimeSinceLastBrickMoveSignal -= BrickMoveSignalInterval;
   323→
   324→		++BrickMoveSignalCount;
   325→
   326→		bool bAnySafeZoneExist = false;
   327→		ShrinkSafeZones(bAnySafeZoneExist);
   328→
   329→		if (bAnySafeZoneExist)
   330→		{
   331→			if (WallManager)
   332→			{
   333→				WallManager->WallMoveStart(UWjWorldWallManager::GetBrickMovementAllowedTime(BrickMoveSignalCount));
   334→			}
   335→
   336→			GameLevelUp(BrickMoveSignalCount);
   337→			UpdateGameData();
   338→
   339→			if (PredictNextLevelIsLast())
   340→			{
   341→				OnGameEndPredict(BrickMoveSignalInterval);
   342→			}
   343→		}
   344→		else
   345→		{
   346→			bGameOverConditionMet = true;
   347→			UE_LOG(LogWjWorld, Log, TEXT("No Safe Zone Exist. Game Over Condition Met."));
   348→
   349→			// 안전 구역이 없어져서 게임이 끝날 때, 마지막 생존자가 승자
   350→			if (AlivePlayerCount == 1 && AlivePlayers.Num() > 0)
   351→			{
   352→				for (const auto& AlivePlayer : AlivePlayers)
   353→				{
   354→					if (AlivePlayer.IsValid())
   355→					{
   356→						WinnerPlayer = AlivePlayer;
   357→						break;
   358→					}
   359→				}
   360→				UE_LOG(LogWjWorld, Log, TEXT("Last player standing wins: %s"),
   361→					WinnerPlayer.IsValid() ? *WinnerPlayer->GetPlayerName() : TEXT("None"));
   362→			}
   363→
   364→			OnGameEnd();
   365→		}
   366→	}
   367→
   368→	if (WallManager)
   369→	{
   370→		WallManager->Tick(DeltaTime);
   371→	}
   372→}
