   465→void UWjWorldGameRuleApproachingWall::ShrinkSafeZones(bool& bAnySafeZoneExist)
   466→{
   467→	FloodFillPoints.Empty();
   468→
   469→	for (auto Iter = CurrentSafeZonePoints.CreateIterator(); Iter; ++Iter)
   470→	{
   471→		FIntPoint& SafeZonePoint = *Iter;
   472→		TArray<FIntPoint> AdjacentPoints = {
   473→			FIntPoint(SafeZonePoint.X + 1, SafeZonePoint.Y),
   474→			FIntPoint(SafeZonePoint.X - 1, SafeZonePoint.Y),
   475→			FIntPoint(SafeZonePoint.X, SafeZonePoint.Y + 1),
   476→			FIntPoint(SafeZonePoint.X, SafeZonePoint.Y - 1),
   477→			FIntPoint(SafeZonePoint.X + 1, SafeZonePoint.Y + 1),
   478→			FIntPoint(SafeZonePoint.X - 1, SafeZonePoint.Y + 1),
   479→			FIntPoint(SafeZonePoint.X + 1, SafeZonePoint.Y - 1),
   480→			FIntPoint(SafeZonePoint.X - 1, SafeZonePoint.Y - 1)
   481→		};
   482→
   483→		for (const FIntPoint& AdjacentPoint : AdjacentPoints)
   484→		{
   485→			if (CurrentSafeZonePoints.Contains(AdjacentPoint) == false)
   486→			{
   487→				FloodFillPoints.Add(SafeZonePoint);
   488→				break;
   489→			}
   490→		}
   491→	}
   492→
   493→	for(const FIntPoint& PointToRemove : FloodFillPoints)
   494→	{
   495→		CurrentSafeZonePoints.Remove(PointToRemove);
   496→	}
   497→
   498→	bAnySafeZoneExist = CurrentSafeZonePoints.Num() > 1;
   499→}
