   501→bool UWjWorldGameRuleApproachingWall::PredictNextLevelIsLast()
   502→{
   503→	TSet<FIntPoint> SimulatedSafeZones = CurrentSafeZonePoints;
   504→	TSet<FIntPoint> SimulatedFloodFillPoints;
   505→
   506→	for (auto Iter = SimulatedSafeZones.CreateIterator(); Iter; ++Iter)
   507→	{
   508→		FIntPoint& SafeZonePoint = *Iter;
   509→		TArray<FIntPoint> AdjacentPoints = {
   510→			FIntPoint(SafeZonePoint.X + 1, SafeZonePoint.Y),
   511→			FIntPoint(SafeZonePoint.X - 1, SafeZonePoint.Y),
   512→			FIntPoint(SafeZonePoint.X, SafeZonePoint.Y + 1),
   513→			FIntPoint(SafeZonePoint.X, SafeZonePoint.Y - 1),
   514→			FIntPoint(SafeZonePoint.X + 1, SafeZonePoint.Y + 1),
   515→			FIntPoint(SafeZonePoint.X - 1, SafeZonePoint.Y + 1),
   516→			FIntPoint(SafeZonePoint.X + 1, SafeZonePoint.Y - 1),
   517→			FIntPoint(SafeZonePoint.X - 1, SafeZonePoint.Y - 1)
   518→		};
   519→
   520→		for (const FIntPoint& AdjacentPoint : AdjacentPoints)
   521→		{
   522→			if (SimulatedSafeZones.Contains(AdjacentPoint) == false)
   523→			{
   524→				SimulatedFloodFillPoints.Add(SafeZonePoint);
   525→				break;
   526→			}
   527→		}
   528→	}
   529→
   530→	for (const FIntPoint& PointToRemove : SimulatedFloodFillPoints)
   531→	{
   532→		SimulatedSafeZones.Remove(PointToRemove);
   533→	}
   534→
   535→	return SimulatedSafeZones.Num() <= 1;
   536→}
