   211→void UWjWorldGameRuleSumo::OnPlayerEliminated(AWjWorldCharacterPlay* EliminatedCharacter)
   212→{
   213→	if (!HasAuthority() || !EliminatedCharacter) return;
   214→	if (EliminatedCharacter->IsEliminated()) return;
   215→
   216→	AWjWorldPlayerStatePlay* VictimPS = EliminatedCharacter->GetPlayerState<AWjWorldPlayerStatePlay>();
   217→	FString VictimName = VictimPS ? VictimPS->GetPlayerName() : TEXT("Unknown");
   218→
   219→	// ???ㅽ꺈 湲곕줉 + ?ы뵾??
   220→	AWjWorldCharacterPlay* Attacker = EliminatedCharacter->GetLastAttacker();
   221→	FString KillerName;
   222→	if (Attacker && !Attacker->IsEliminated())
   223→	{
   224→		AWjWorldPlayerStatePlay* AttackerPS = Attacker->GetPlayerState<AWjWorldPlayerStatePlay>();
   225→		if (AttackerPS)
   226→		{
   227→			KillerName = AttackerPS->GetPlayerName();
   228→			RecordKillStat(AttackerPS);
   229→		}
   230→	}
   231→
   232→	// ?ы뵾??釉뚮줈?쒖틦?ㅽ듃
   233→	BroadcastKillFeed(KillerName, VictimName);
   234→
   235→	// 罹먮┃???쒓굅
   236→	EliminatedCharacter->OnEliminated();
   237→
   238→	// PlayerData ?낅뜲?댄듃
   239→	if (VictimPS)
   240→	{
   241→		if (USumoPlayerDataComponent* PlayerData = VictimPS->GetGameData<USumoPlayerDataComponent>())
   242→		{
   243→			PlayerData->OnEliminated();
   244→		}
   245→
   246→		// ?덈씫 ?쒖꽌 湲곕줉
   247→		EliminationOrder.Add(VictimPS);
   248→
   249→		if (AlivePlayers.Remove(VictimPS) > 0)
   250→		{
   251→			AlivePlayerCount--;
   252→		}
   253→
   254→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleSumo: Player eliminated: %s. Alive: %d (Round %d)"),
   255→			*VictimPS->GetPlayerName(), AlivePlayerCount, CurrentRound);
   256→	}
   257→
   258→	UpdateGameData();
   259→
   260→	// ?숈떆 ?꾩썝 ?덈씫
   261→	if (AlivePlayerCount == 0)
   262→	{
   263→		OnRoundEnd();
   264→		return;
   265→	}
   266→
   267→	// ?쇱슫???밸━ 議곌굔 (1紐??댄븯 ?앹〈)
   268→	if (bIsGameStarted && bIsRoundActive && AlivePlayerCount <= 1)
   269→	{
   270→		OnRoundEnd();
   271→	}
   272→}
