   341→void UWjWorldGameRuleSumo::AwardRoundScores()
   342→{
   343→	// ?덈씫 ?쒖꽌 ??닚?쇰줈 ?먯닔 遺??
   344→	// 泥?踰덉㎏ ?덈씫 = 1?? ??踰덉㎏ = 2?? ... 留덉?留??앹〈 = N??
   345→	int32 NumPlayers = EliminationOrder.Num();
   346→	for (int32 i = 0; i < NumPlayers; i++)
   347→	{
   348→		if (EliminationOrder[i].IsValid())
   349→		{
   350→			int32 Score = i + 1; // 泥??덈씫??1?? 留덉?留??앹〈??N??
   351→			AWjWorldPlayerStatePlay* PS = EliminationOrder[i].Get();
   352→			if (USumoPlayerDataComponent* PlayerData = PS->GetGameData<USumoPlayerDataComponent>())
   353→			{
   354→				PlayerData->AddScore(Score);
   355→				UE_LOG(LogWjWorld, Log, TEXT("GameRuleSumo: Round score - %s: +%d (Total: %d)"),
   356→					*PS->GetPlayerName(), Score, PlayerData->GetTotalScore());
   357→			}
   358→		}
   359→	}
