   362→void UWjWorldGameRuleSumo::UpdatePlayerScores()
   363→{
   364→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   365→	if (!GameState) return;
   366→
   367→	USumoGameDataComponent* GameData = GameState->GetGameData<USumoGameDataComponent>();
   368→	if (!GameData) return;
   369→
   370→	TArray<FSumoPlayerScore> Scores;
   371→	for (const auto& WeakPS : AllPlayers)
   372→	{
   373→		if (!WeakPS.IsValid()) continue;
   374→		AWjWorldPlayerStatePlay* PS = WeakPS.Get();
   375→		USumoPlayerDataComponent* PlayerData = PS->GetGameData<USumoPlayerDataComponent>();
   376→
   377→		FSumoPlayerScore Entry;
   378→		Entry.PlayerName = PS->GetPlayerName();
   379→		Entry.Score = PlayerData ? PlayerData->GetTotalScore() : 0;
   380→		Scores.Add(Entry);
   381→	}
   382→
   383→	// ?먯닔 ?대┝李⑥닚 ?뺣젹
   384→	Scores.Sort([](const FSumoPlayerScore& A, const FSumoPlayerScore& B) { return A.Score > B.Score; });
   385→	GameData->SetPlayerScores(Scores);
   386→}
