   388→AWjWorldPlayerStatePlay* UWjWorldGameRuleSumo::GetFinalWinner() const
   389→{
   390→	AWjWorldPlayerStatePlay* BestPlayer = nullptr;
   391→	int32 BestScore = -1;
   392→
   393→	for (const auto& WeakPS : AllPlayers)
   394→	{
   395→		if (!WeakPS.IsValid()) continue;
   396→		AWjWorldPlayerStatePlay* PS = WeakPS.Get();
   397→		USumoPlayerDataComponent* PlayerData = PS->GetGameData<USumoPlayerDataComponent>();
   398→		int32 Score = PlayerData ? PlayerData->GetTotalScore() : 0;
   399→
   400→		if (Score > BestScore)
   401→		{
   402→			BestScore = Score;
   403→			BestPlayer = PS;
   404→		}
   405→	}
   406→
   407→	return BestPlayer;
   408→}
