   410→void UWjWorldGameRuleSumo::ResetRound()
   411→{
   412→	bIsResettingRound = false;
   413→
   414→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleSumo: Resetting for round %d"), CurrentRound + 1);
   415→
   416→	UWorld* World = GetWorld();
   417→	if (!World) return;
   418→
   419→	// ?뚯썙???뺣━
   420→	CleanupPowerUps();
   421→
   422→	// 踰꾪봽 ?뺣━
   423→	RemoveAllPlayerBuffs();
   424→
   425→	// ?뚮옯??蹂듭썝
   426→	for (ASumoFloorRingActor* Ring : FloorRings)
   427→	{
   428→		if (Ring)
   429→		{
   430→			Ring->ResetRing();
   431→		}
   432→	}
   433→	CurrentShrinkLevel = 0;
   434→	TimeSinceLastShrink = 0.f;
   435→	bIsWarningActive = false;
   436→	WarningElapsed = 0.f;
   437→	TimeSinceLastPowerUp = 0.f;
   438→
   439→	// ?덈씫 ?쒖꽌 珥덇린??
   440→	EliminationOrder.Empty();
   441→
   442→	// 紐⑤뱺 ?뚮젅?댁뼱 由ъ뒪??
   443→	AlivePlayers.Empty();
   444→	AlivePlayerCount = 0;
   445→
   446→	AWjWorldGameModePlay* GM = GetGameModePlay();
   447→	if (!GM) return;
   448→
   449→	for (const auto& WeakPS : AllPlayers)
   450→	{
   451→		if (!WeakPS.IsValid()) continue;
   452→		AWjWorldPlayerStatePlay* PS = WeakPS.Get();
   453→
   454→		// PlayerData 由ъ뀑
   455→		if (USumoPlayerDataComponent* PlayerData = PS->GetGameData<USumoPlayerDataComponent>())
   456→		{
   457→			PlayerData->ResetForNewRound();
   458→		}
   459→
   460→		AlivePlayers.Add(PS);
   461→		AlivePlayerCount++;
   462→
   463→		// 罹먮┃??由ъ뒪??
   464→		APlayerController* PC = Cast<APlayerController>(PS->GetOwner());
   465→		if (PC)
   466→		{
   467→			// 湲곗〈 Pawn ?뚭눼
   468→			// 기존 Pawn 제거 (이미 Destroy된 경우 무시)
   469→			if (APawn* OldPawn = PC->GetPawn())
   470→			{
   471→				if (::IsValid(OldPawn))
   472→				{
   473→					OldPawn->Destroy();
   474→				}
   475→			}
   476→
   477→			// UnPossess 후 RestartPlayer (Pawn 없이 리스폰 보장)
   478→			PC->UnPossess();
   479→			GM->RestartPlayer(PC);
   480→
   481→			// 리스폰 성공 확인
   482→			if (APawn* NewPawn = PC->GetPawn())
   483→			{
   484→				UE_LOG(LogWjWorld, Log, TEXT("GameRuleSumo: Player %s respawned successfully"), *PS->GetPlayerName());
   485→			}
   486→			else
   487→			{
   488→				UE_LOG(LogWjWorld, Warning, TEXT("GameRuleSumo: Player %s respawn FAILED"), *PS->GetPlayerName());
   489→			}
   490→		}
   491→	}
   492→
   493→	// ?쇱슫???쒖옉
   494→	OnRoundStart();
   495→}
