   547→void UWjWorldGameRuleSumo::CheckFallenPlayers()
   548→{
   549→	TArray<AWjWorldCharacterPlay*> FallenCharacters;
   550→
   551→	for (const auto& WeakPS : AlivePlayers)
   552→	{
   553→		if (!WeakPS.IsValid()) continue;
   554→
   555→		APawn* Pawn = WeakPS->GetPawn();
   556→		AWjWorldCharacterPlay* Character = Cast<AWjWorldCharacterPlay>(Pawn);
   557→		if (!Character || Character->IsEliminated()) continue;
   558→
   559→		if (Character->GetActorLocation().Z < FallThresholdZ)
   560→		{
   561→			FallenCharacters.Add(Character);
   562→		}
   563→	}
   564→
   565→	for (AWjWorldCharacterPlay* Fallen : FallenCharacters)
   566→	{
   567→		OnPlayerEliminated(Fallen);
