   626→void UWjWorldGameRuleSumo::TickShrinkPlatform(float DeltaTime)
   627→{
   628→	if (FloorRings.Num() == 0) return;
   629→
   630→	// Warning 以묒씠硫?寃쎄퀬 ?쒓컙 泥댄겕
   631→	if (bIsWarningActive)
   632→	{
   633→		WarningElapsed += DeltaTime;
   634→		if (WarningElapsed >= WarningDuration)
   635→		{
   636→			// Warning ?꾨즺 ??留??뚭눼
   637→			for (ASumoFloorRingActor* Ring : FloorRings)
   638→			{
   639→				if (Ring && Ring->GetRingState() == ESumoRingState::Warning)
   640→				{
   641→					Ring->DestroyRing();
   642→				}
   643→			}
   644→			bIsWarningActive = false;
   645→			WarningElapsed = 0.f;
   646→			CurrentShrinkLevel++;
   647→		}
   648→		return;
   649→	}
   650→
   651→	TimeSinceLastShrink += DeltaTime;
   652→	if (TimeSinceLastShrink >= ShrinkInterval)
   653→	{
   654→		TimeSinceLastShrink = 0.f;
   655→
   656→		// ?ㅼ쓬 ?뚭눼 ???留?李얘린
   657→		ASumoFloorRingActor* TargetRing = nullptr;
   658→		for (ASumoFloorRingActor* Ring : FloorRings)
   659→		{
   660→			if (Ring && Ring->GetRingState() == ESumoRingState::Active && Ring->RingOrder > 0)
   661→			{
