   732→FVector UWjWorldGameRuleSumo::GetRandomSpawnLocationOnActiveRings() const
   733→{
   734→	// Active ?곹깭??留?以??섎굹瑜??쒕뜡 ?좏깮
   735→	TArray<ASumoFloorRingActor*> ActiveRings;
   736→	for (ASumoFloorRingActor* Ring : FloorRings)
   737→	{
   738→		if (Ring && Ring->GetRingState() == ESumoRingState::Active)
   739→		{
   740→			ActiveRings.Add(Ring);
   741→		}
   742→	}
   743→
   744→	if (ActiveRings.Num() > 0)
   745→	{
   746→		ASumoFloorRingActor* ChosenRing = ActiveRings[FMath::RandRange(0, ActiveRings.Num() - 1)];
   747→		FVector Center = ChosenRing->GetActorLocation();
   748→		float Radius = ChosenRing->RingRadius;
   749→
   750→		// 留????쒕뜡 ?꾩튂
   751→		float Angle = FMath::FRandRange(0.f, 2.f * PI);
   752→		float Dist = FMath::FRandRange(0.f, Radius);
   753→		return Center + FVector(FMath::Cos(Angle) * Dist, FMath::Sin(Angle) * Dist, 0.f);
   754→	}
   755→
   756→	return FVector::ZeroVector;
   757→}
