    72→	// ACharacter에서 메시 컴포넌트 가져오기
    73→	ACharacter* SourceCharacter = Cast<ACharacter>(SourcePawn);
    74→	if (!SourceCharacter)
    75→	{
    76→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("CharacterPreviewActor: SourcePawn is not a Character"));
    77→		return;
    78→	}
    79→
    80→	USkeletalMeshComponent* SourceMesh = SourceCharacter->GetMesh();
    81→	if (!SourceMesh)
    82→	{
    83→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("CharacterPreviewActor: Source character has no mesh"));
    84→		return;
    85→	}
    86→
    87→	// SkeletalMesh 복사
    88→	USkeletalMesh* SkelMesh = SourceMesh->GetSkeletalMeshAsset();
    89→	if (SkelMesh)
    90→	{
    91→		PreviewMeshComponent->SetSkeletalMesh(SkelMesh);
    92→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("CharacterPreviewActor: Copied SkeletalMesh %s"), *SkelMesh->GetName());
    93→	}
    94→
    95→	// AnimBlueprint 복사
    96→	UClass* AnimClass = SourceMesh->GetAnimClass();
    97→	if (AnimClass)
    98→	{
    99→		PreviewMeshComponent->SetAnimInstanceClass(AnimClass);
   100→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("CharacterPreviewActor: Copied AnimBlueprint %s"), *AnimClass->GetName());
   101→	}
   102→
   103→	// 애니메이션 재생을 위해 가시성 및 틱 활성화
   104→	PreviewMeshComponent->SetVisibility(true);
   105→	PreviewMeshComponent->VisibilityBasedAnimTickOption = EVisibilityBasedAnimTickOption::AlwaysTickPoseAndRefreshBones;
   106→
   107→	RefreshCapture();
   108→}
