    48→void UWjWorldCosmeticComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
    49→{
    50→	// 비동기 로드 핸들 정리
    51→	for (auto& Pair : ActiveStreamHandles)
    52→	{
    53→		if (Pair.Value.IsValid())
    54→		{
    55→			Pair.Value->CancelHandle();
    56→		}
    57→	}
    58→	ActiveStreamHandles.Reset();
    59→
    60→	// CosmeticSubsystem 구독 해제
    61→	if (UGameInstance* GI = GetWorld()->GetGameInstance())
    62→	{
    63→		if (UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>())
    64→		{
    65→			CosmeticSub->OnLoadoutChanged.RemoveDynamic(this, &ThisClass::OnLoadoutChangedHandler);
    66→		}
    67→	}
    68→
    69→	Super::EndPlay(EndPlayReason);
    70→}
