   154→void UWjWorldCosmeticComponent::ClearSlot(ECosmeticSlot Slot)
   155→{
   156→	// 비동기 핸들 취소
   157→	if (TSharedPtr<FStreamableHandle>* Handle = ActiveStreamHandles.Find(Slot))
   158→	{
   159→		if (Handle->IsValid())
   160→		{
   161→			(*Handle)->CancelHandle();
   162→		}
   163→		ActiveStreamHandles.Remove(Slot);
   164→	}
   165→
   166→	AppliedLoadout.Unequip(Slot);
   167→	RestoreDefaultMesh(Slot);
   168→
   169→	// 동적 메시 컴포넌트 제거
   170→	if (TObjectPtr<UMeshComponent>* MeshComp = SlotMeshComponents.Find(Slot))
   171→	{
   172→		if (*MeshComp)
   173→		{
   174→			(*MeshComp)->DestroyComponent();
   175→		}
   176→		SlotMeshComponents.Remove(Slot);
   177→	}
   178→}
