   752→void UCosmeticMainWindow::PopulateShopItems()
   753→{
   754→	UGameInstance* GI = GetGameInstance();
   755→	if (!GI)
   756→	{
   757→		return;
   758→	}
   759→
   760→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   761→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   762→	{
   763→		return;
   764→	}
   765→
   766→	UWjWorldCosmeticCatalogDataAsset* Catalog = CosmeticSub->GetCatalog();
   767→	TArray<const FCosmeticItemDefinition*> Items = Catalog->GetItemsBySlot(CurrentSlot);
   768→
   769→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   770→
   771→	int32 Index = 0;
   772→	for (const FCosmeticItemDefinition* ItemDef : Items)
   773→	{
   774→		if (!ItemDef || !ItemDef->IsValid())
   775→		{
   776→			continue;
   777→		}
   778→
   779→		UCosmeticItemEntryWidget* EntryWidget = CreateItemEntry(*ItemDef);
   780→		if (!EntryWidget)
   781→		{
   782→			continue;
   783→		}
   784→
   785→		// 보유/장착 상태 설정
   786→		bool bOwned = CosmeticSub->HasItem(ItemDef->ItemId);
   787→		bool bEquipped = Loadout.GetEquippedItem(CurrentSlot) == ItemDef->ItemId;
   788→
   789→		EntryWidget->SetOwned(bOwned);
   790→		EntryWidget->SetEquipped(bEquipped);
   791→		EntryWidget->SetSelected(ItemDef->ItemId == SelectedItemId);
   792→
   793→		// 그리드에 추가
   794→		if (ItemGridPanel)
   795→		{
   796→			ItemGridPanel->AddChildToUniformGrid(EntryWidget, Index / GridColumnCount, Index % GridColumnCount);
   797→		}
   798→
   799→		ItemEntryWidgets.Add(EntryWidget);
   800→		Index++;
   801→	}
