   115→void ACharacterPreviewActor::SetupPreview(const FCosmeticLoadout& Loadout)
   116→{
   117→	// 기존 코스메틱 메시 제거
   118→	for (auto& Pair : SlotMeshComponents)
   119→	{
   120→		if (Pair.Value)
   121→		{
   122→			Pair.Value->DestroyComponent();
   123→		}
   124→	}
   125→	SlotMeshComponents.Empty();
   126→	ActiveStreamHandles.Empty();
   127→
   128→	// 카탈로그 가져오기
   129→	UGameInstance* GI = GetGameInstance();
   130→	if (!GI)
   131→	{
   132→		return;
   133→	}
   134→
   135→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   136→	if (!CosmeticSub)
   137→	{
   138→		return;
   139→	}
   140→
   141→	UWjWorldCosmeticCatalogDataAsset* Catalog = CosmeticSub->GetCatalog();
   142→	if (!Catalog)
   143→	{
   144→		RefreshCapture();
   145→		return;
   146→	}
   147→
   148→	// 코스메틱 로드아웃 적용
   149→	for (const FCosmeticSlotEntry& Entry : Loadout.Entries)
   150→	{
   151→		if (Entry.Slot == ECosmeticSlot::None || Entry.ItemId.IsNone())
   152→		{
   153→			continue;
   154→		}
   155→
   156→		const FCosmeticItemDefinition* ItemDef = Catalog->FindByItemId(Entry.ItemId);
   157→		if (!ItemDef)
   158→		{
   159→			continue;
   160→		}
   161→
   162→		// StaticMesh 또는 SkeletalMesh 비동기 로드
   163→		FSoftObjectPath MeshPath;
   164→		if (!ItemDef->StaticMesh.IsNull())
   165→		{
   166→			MeshPath = ItemDef->StaticMesh.ToSoftObjectPath();
   167→		}
   168→		else if (!ItemDef->SkeletalMesh.IsNull())
   169→		{
   170→			MeshPath = ItemDef->SkeletalMesh.ToSoftObjectPath();
   171→		}
   172→
   173→		if (!MeshPath.IsNull())
   174→		{
   175→			ECosmeticSlot CapturedSlot = Entry.Slot;
   176→			FName CapturedItemId = Entry.ItemId;
   177→
   178→			TSharedPtr<FStreamableHandle> Handle = StreamableManager.RequestAsyncLoad(
   179→				MeshPath,
   180→				FStreamableDelegate::CreateWeakLambda(this, [this, CapturedSlot, CapturedItemId]()
   181→				{
   182→					OnCosmeticAssetLoaded(CapturedSlot, CapturedItemId);
   183→				})
   184→			);
   185→
   186→			if (Handle.IsValid())
   187→			{
   188→				ActiveStreamHandles.Add(CapturedSlot, Handle);
   189→			}
   190→		}
   191→	}
   192→
   193→	// 코스메틱이 없으면 바로 캡처
   194→	if (Loadout.IsEmpty())
   195→	{
   196→		RefreshCapture();
   197→	}
   198→}
   199→
   200→void ACharacterPreviewActor::OnCosmeticAssetLoaded(ECosmeticSlot Slot, FName ItemId)
   201→{
   202→	UGameInstance* GI = GetGameInstance();
   203→	if (!GI)
   204→	{
   205→		return;
   206→	}
   207→
   208→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   209→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   210→	{
   211→		return;
   212→	}
   213→
   214→	const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog()->FindByItemId(ItemId);
   215→	if (!ItemDef)
   216→	{
   217→		return;
   218→	}
   219→
   220→	// StaticMesh 우선, 없으면 SkeletalMesh 시도
   221→	UObject* LoadedAsset = nullptr;
   222→	if (!ItemDef->StaticMesh.IsNull())
   223→	{
   224→		LoadedAsset = ItemDef->StaticMesh.ToSoftObjectPath().ResolveObject();
   225→	}
   226→	else if (!ItemDef->SkeletalMesh.IsNull())
   227→	{
   228→		LoadedAsset = ItemDef->SkeletalMesh.ToSoftObjectPath().ResolveObject();
   229→	}
   230→
   231→	// 부착 소켓 결정
   232→	FName SocketName = ItemDef->AttachSocketName;
   233→	if (SocketName.IsNone())
   234→	{
   235→		SocketName = GetDefaultSocketName(ItemDef->Slot);
   236→	}
   237→
   238→	// 메시 컴포넌트 생성 및 부착
   239→	UMeshComponent* NewMeshComp = nullptr;
   240→
   241→	if (UStaticMesh* StaticMesh = Cast<UStaticMesh>(LoadedAsset))
   242→	{
   243→		UStaticMeshComponent* StaticMeshComp = NewObject<UStaticMeshComponent>(this);
   244→		StaticMeshComp->SetCollisionEnabled(ECollisionEnabled::NoCollision);
   245→		StaticMeshComp->SetStaticMesh(StaticMesh);
   246→		NewMeshComp = StaticMeshComp;
   247→	}
   248→	else if (USkeletalMesh* SkeletalMesh = Cast<USkeletalMesh>(LoadedAsset))
   249→	{
   250→		USkeletalMeshComponent* SkelMeshComp = NewObject<USkeletalMeshComponent>(this);
   251→		SkelMeshComp->SetCollisionEnabled(ECollisionEnabled::NoCollision);
   252→		SkelMeshComp->SetSkeletalMesh(SkeletalMesh);
   253→		NewMeshComp = SkelMeshComp;
   254→	}
   255→
   256→	if (NewMeshComp)
   257→	{
   258→		// Socket 부착 또는 단순 부착
   259→		if (!SocketName.IsNone() && PreviewMeshComponent->DoesSocketExist(SocketName))
   260→		{
   261→			NewMeshComp->AttachToComponent(PreviewMeshComponent,
   262→				FAttachmentTransformRules::SnapToTargetNotIncludingScale, SocketName);
   263→		}
   264→		else
   265→		{
   266→			NewMeshComp->SetupAttachment(PreviewMeshComponent);
   267→		}
   268→
   269→		// 오프셋 및 스케일 적용
   270→		NewMeshComp->SetRelativeLocation(ItemDef->AttachLocationOffset);
   271→		NewMeshComp->SetRelativeRotation(ItemDef->AttachRotationOffset);
   272→		NewMeshComp->SetRelativeScale3D(ItemDef->AttachScale);
   273→
   274→		NewMeshComp->RegisterComponent();
   275→
   276→		SlotMeshComponents.Add(Slot, NewMeshComp);
   277→		SceneCaptureComponent->ShowOnlyComponents.Add(NewMeshComp);
   278→
   279→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("CharacterPreviewActor: Loaded cosmetic %s on slot %d (socket: %s)"),
   280→			*ItemId.ToString(), static_cast<int32>(Slot), *SocketName.ToString());
   281→	}
   282→
   283→	// 모든 로드가 완료되었는지 확인
   284→	ActiveStreamHandles.Remove(Slot);
   285→	if (ActiveStreamHandles.Num() == 0)
   286→	{
   287→		RefreshCapture();
   288→	}
   289→}
   290→
   291→FName ACharacterPreviewActor::GetDefaultSocketName(ECosmeticSlot Slot)
   292→{
   293→	switch (Slot)
   294→	{
   295→	case ECosmeticSlot::Head:
   296→		return FName("head");
   297→	case ECosmeticSlot::Back:
   298→		return FName("spine_03");
   299→	case ECosmeticSlot::Effect:
   300→		return FName("root");
   301→	default:
   302→		return NAME_None;
   303→	}
   304→}
   305→
   306→void ACharacterPreviewActor::RefreshCapture()
   307→{
   308→	if (SceneCaptureComponent && RenderTarget)
   309→	{
   310→		SceneCaptureComponent->CaptureScene();
   311→
   312→		UE_LOG(LogWjWorld, Log, TEXT("CharacterPreviewActor: Scene captured"));
   313→	}
   314→}
