   180→void UWjWorldCosmeticComponent::ClearAll()
   181→{
   182→	TArray<ECosmeticSlot> Slots = AppliedLoadout.GetEquippedSlots();
   183→
   184→	for (ECosmeticSlot Slot : Slots)
   185→	{
   186→		ClearSlot(Slot);
   187→	}
   188→
   189→	AppliedLoadout.Reset();
   190→}
