   359→void UWjWorldCosmeticComponent::OnLoadoutChangedHandler(ECosmeticSlot Slot, FName ItemId)
   360→{
   361→	// 로컬 플레이어 캐릭터만 처리 (멀티플레이어에서 다른 플레이어 캐릭터 제외)
   362→	APawn* OwnerPawn = Cast<APawn>(GetOwner());
   363→	if (!OwnerPawn)
   364→	{
   365→		return;
   366→	}
   367→
   368→	// 로컬 컨트롤 여부 확인
   369→	if (!OwnerPawn->IsLocallyControlled())
   370→	{
   371→		return;
   372→	}
   373→
   374→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticComponent: 로드아웃 변경 감지 - 슬롯 %d, 아이템 %s"),
   375→		static_cast<int32>(Slot), *ItemId.ToString());
   376→
   377→	if (ItemId.IsNone())
   378→	{
   379→		// 아이템 해제
   380→		ClearSlot(Slot);
   381→	}
   382→	else
   383→	{
   384→		// 아이템 장착
   385→		ApplySlot(Slot, ItemId);
   386→	}
   387→}
