		PreviewMeshComponent->SetSkeletalMesh(SkelMesh);
	}

	// PATTERN 2: AnimBlueprint Direct Assignment (NO DUPLICATION)
	UClass* AnimClass = SourceMesh->GetAnimClass();
	if (AnimClass)
	{
		PreviewMeshComponent->SetAnimInstanceClass(AnimClass);
	}

