   313→void UPlayerProfileWidget::ApplyRenderTargetToImage()
   314→{
   315→	if (!CharacterPreviewImage || !PreviewActor)
   316→	{
   317→		return;
   318→	}
   319→
   320→	UTextureRenderTarget2D* RT = PreviewActor->GetRenderTarget();
   321→	if (!RT)
   322→	{
   323→		return;
   324→	}
   325→
   326→	// RenderTarget을 브러시로 설정
   327→	FSlateBrush Brush;
   328→	Brush.SetResourceObject(RT);
   329→	Brush.ImageSize = FVector2D(RT->SizeX, RT->SizeY);
   330→	CharacterPreviewImage->SetBrush(Brush);
   331→
   332→	UE_LOG(LogWjWorld, Log, TEXT("PlayerProfileWidget: RenderTarget applied to image"));
   333→}
